import sys
import math

MOD = 998244353

def calculate(n, x, even, odd, c0, c1):
    if x == 0:
        if n in c0:
            return c0[n]
        if n == 1:
            return even
        if n == 2:
            return (even * even + odd * odd) % MOD
        a = calculate(n // 2, 0, even, odd, c0, c1)
        b = calculate(n - n // 2, 0, even, odd, c0, c1)
        c = calculate(n // 2, 1, even, odd, c0, c1)
        d = calculate(n - n // 2, 1, even, odd, c0, c1)
        res = (a * b + c * d) % MOD
        c0[n] = res
        return res
    else:
        if n in c1:
            return c1[n]
        if n == 1:
            return odd
        if n == 2:
            return (even * odd + odd * even) % MOD
        a = calculate(n // 2, 0, even, odd, c0, c1)
        b = calculate(n - n // 2, 1, even, odd, c0, c1)
        c = calculate(n // 2, 1, even, odd, c0, c1)
        d = calculate(n - n // 2, 0, even, odd, c0, c1)
        res = (a * b + c * d) % MOD
        c1[n] = res
        return res

def power_mod(base, exp):
    res = 1
    while exp > 0:
        if exp & 1:
            res = (res * base) % MOD
        base = (base * base) % MOD
        exp >>= 1
    return res

def main():
    input_line = sys.stdin.readline().strip()
    tokens = input_line.split()
    n = int(tokens[0])
    m = int(tokens[1])
    start = int(tokens[2])
    end = int(tokens[3])

    total_cells = n * m

    if total_cells % 2 == 0:
        length = end - start + 1
        even_count = length // 2
        if length % 2 == 0 and start % 2 == 0:
            even_count += 1
        odd_count = length - even_count

        c0 = {}
        c1 = {}
        print(calculate(total_cells, 0, even_count, odd_count, c0, c1))
    else:
        answer = power_mod(end - start + 1, total_cells)
        print(answer)

if __name__ == "__main__":
    main()

